def isBetween(x: float, left: float, right: float) -> bool:
    if left > right:
        return False
    if x < left:
        return False
    if x > right:
        return False
    return True

def main():
    test_cases = [
        (5.0, 1.0, 10.0),
        (0.0, -1.0, 1.0),
        (10.0, 10.0, 10.0),
        (15.0, 10.0, 20.0),
        (9.0, 10.0, 20.0),
        (25.0, 10.0, 20.0),
        (5.0, 20.0, 10.0),
        (-5.0, -10.0, 0.0),
        (0.0, 0.0, 0.0),
        (3.14, 3.0, 4.0)
    ]

    for x, left, right in test_cases:
        result = isBetween(x, left, right)
        print(result)

if __name__ == "__main__":
    main()

