#include <stdio.h>
#include <stdbool.h>

bool isBetween(double x, double left, double right) {
    if (!(left > right)) {
        if (!(x < left)) {
            if (!(x > right)) {
                return true;
            }
        }
    }
    return false;
}

int main() {
    // Test case 1: normal case, inside range
    printf("%d\n", isBetween(5.0, 1.0, 10.0));

    // Test case 2: at left boundary
    printf("%d\n", isBetween(1.0, 1.0, 10.0));

    // Test case 3: at right boundary
    printf("%d\n", isBetween(10.0, 1.0, 10.0));

    // Test case 4: below range
    printf("%d\n", isBetween(0.5, 1.0, 10.0));

    // Test case 5: above range
    printf("%d\n", isBetween(10.5, 1.0, 10.0));

    // Test case 6: reversed bounds (should always be false)
    printf("%d\n", isBetween(5.0, 10.0, 1.0));

    // Test case 7: zero values
    printf("%d\n", isBetween(0.0, 0.0, 0.0));

    // Test case 8: negative range
    printf("%d\n", isBetween(-2.0, -5.0, 5.0));

    // Test case 9: exactly in middle
    printf("%d\n", isBetween(0.0, -1.0, 1.0));

    // Test case 10: floating point precision test
    printf("%d\n", isBetween(0.1 + 0.2, 0.3, 0.3));

    return 0;
}

