public class Solution {
    public static boolean isBetween(double x, double left, double right) {
        if (!(left > x)) {
            if (!(x > right)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        System.out.println(isBetween(5.0, 1.0, 10.0));
        System.out.println(isBetween(0.0, -1.0, 1.0));
        System.out.println(isBetween(10.0, 10.0, 20.0));
        System.out.println(isBetween(20.0, 10.0, 20.0));
        System.out.println(isBetween(15.0, 20.0, 10.0));
    }
}
